CREATE COLUMN TABLE "TEST_AP"."ONCP" ("AbsEntry" INTEGER CS_INT NOT NULL , "Name" NVARCHAR(100) NOT NULL , "Owner" INTEGER CS_INT NOT NULL , "GroupId" INTEGER CS_INT, "CreateDate" LONGDATE CS_LONGDATE, "UpdateDate" LONGDATE CS_LONGDATE, "IsPublic" NVARCHAR(1) DEFAULT 'N', "Pubby" NVARCHAR(30), "PubDate" LONGDATE CS_LONGDATE, "Type" NVARCHAR(1) DEFAULT 'T', "Descr" NVARCHAR(100), "Date" LONGDATE CS_LONGDATE, "Time" SMALLINT CS_INT, "Mnfacturer" NVARCHAR(50), PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "ONCP_NAME" ON "TEST_AP"."ONCP" ( "Name" ASC, "Owner" ASC )